<?php
use PHPUnit\Framework\TestCase;
final class Phase9LegacyFlatRatePMMigrationTest extends TestCase {
 public function test_migration_provenance_upgrade_is_versioned(): void {$b=file_get_contents(__DIR__.'/../../servsys.php');$s=file_get_contents(__DIR__.'/../../src/Database/Schema.php');$this->assertStringContainsString("SERVSYS_DB_VERSION', 15",$b);$this->assertStringContainsString('legacy_planrec bigint(20) unsigned NULL',$s);$this->assertStringContainsString('UNIQUE KEY company_legacy_planrec (company_id,legacy_planrec)',$s);$this->assertStringContainsString('UNIQUE KEY company_legacy_contnum (company_id,legacy_contnum)',$s);}
 public function test_tool_is_dry_run_by_default_and_apply_is_explicit(): void {$p=file_get_contents(__DIR__.'/../../tools/legacy-flat-rate-pm-import.php');$this->assertStringContainsString("\$apply=isset(\$options['apply'])",$p);$this->assertStringContainsString('DRY RUN - NO CHANGES',$p);$this->assertStringContainsString('No database changes were made',$p);$this->assertStringContainsString('apply refused because migration mappings are incomplete',$p);}
 public function test_only_authoritative_legacy_sources_are_imported(): void {$p=file_get_contents(__DIR__.'/../../tools/legacy-flat-rate-pm-import.php');foreach(array('flat_rate_cat','flat_rate_table','flatrateconfig','prevprices','pagreement') as $table){$this->assertStringContainsString("'".$table."'",$p);}foreach(array('flat_rate_date','prevprices_date','servsync') as $ignored){$this->assertStringContainsString("'".$ignored."'",$p);}$this->assertStringNotContainsString("servsys_p9_rows(\$sql,'flat_rate')",$p);}
 public function test_flat_rate_migration_preserves_code_flags_material_and_config_semantics(): void {$p=file_get_contents(__DIR__.'/../../tools/legacy-flat-rate-pm-import.php');$this->assertStringContainsString("'code'=>\$code",$p);$this->assertStringContainsString("'no_discount'=>(int)('1'===trim((string)\$r[7]))",$p);$this->assertStringContainsString("'special_item'=>(int)((int)\$r[8]!==0)",$p);$this->assertStringContainsString("'inventory_item_id'=>\$inventory[\$key]",$p);$this->assertStringContainsString("'manual_unit_cost'=>\$cost",$p);$this->assertStringContainsString("'agreement_repair_multiplier'=>(float)\$r[1]",$p);$this->assertStringContainsString("'additional_repair_multiplier'=>(float)\$r[2]",$p);}
 public function test_pm_plan_prices_map_to_normalized_terms(): void {$p=file_get_contents(__DIR__.'/../../tools/legacy-flat-rate-pm-import.php');$this->assertStringContainsString("array(12=>\$r[3],24=>\$r[4],36=>\$r[5])",$p);$this->assertStringContainsString("'legacy_planrec'=>\$planrec",$p);}
 public function test_pm_agreement_column_mapping_accounts_for_servsync_position(): void {$p=file_get_contents(__DIR__.'/../../tools/legacy-flat-rate-pm-import.php');$this->assertStringContainsString('count($r)!==30',$p);$this->assertStringContainsString("array_slice(\$r,20,6)",$p);$this->assertStringContainsString("'visits_per_year'=>max(0,(int)\$r[19])",$p);$this->assertStringContainsString("trim((string)\$r[27])",$p);$this->assertStringContainsString("trim((string)\$r[28])",$p);}
 public function test_pm_visit_parser_preserves_month_year_precision(): void {$p=file_get_contents(__DIR__.'/../../tools/legacy-flat-rate-pm-import.php');$this->assertStringContainsString("'scheduled_year'=>\$period[0]",$p);$this->assertStringContainsString("'scheduled_month'=>\$period[1]",$p);$this->assertStringContainsString("'scheduled_date'=>\$period[2]",$p);}
 public function test_apply_is_transactional_and_reruns_skip_legacy_identifiers(): void {$p=file_get_contents(__DIR__.'/../../tools/legacy-flat-rate-pm-import.php');$this->assertStringContainsString("START TRANSACTION",$p);$this->assertStringContainsString("ROLLBACK",$p);$this->assertStringContainsString('company_id=%d AND legacy_planrec=%d',$p);$this->assertStringContainsString('company_id=%d AND legacy_contnum=%d',$p);}
 public function test_release_build_removes_all_development_tools(): void {$p=file_get_contents(__DIR__.'/../../build-release.sh');$this->assertStringContainsString('/tools"',$p);$this->assertStringContainsString('"tools/"',$p);}
}
